`timescale 1ns / 1ps
`default_nettype none

// axil_timer: 32-bit down-counting timer with one-shot and periodic modes and
// a level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
//
// Register map (byte offsets):
//   0x0 CTRL    read/write    bit 0 EN, bit 1 IE, bit 2 MODE (0 one-shot, 1 periodic)
//   0x4 LOAD    read/write    count length in clock cycles (0 counts as 1)
//   0x8 COUNT   read only     cycles left; a write gets SLVERR and changes nothing
//   0xC STATUS  write 1 clear bit 0 EXPIRED
// Unaligned addresses and every offset from 0x10 up are unmapped: writes get
// SLVERR and change nothing, reads return zero with SLVERR.

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL    = 2'd0;
    localparam [1:0] IDX_LOAD    = 2'd1;
    localparam [1:0] IDX_COUNT   = 2'd2;
    localparam [1:0] IDX_STATUS  = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    reg                  en;
    reg                  ie;
    reg                  mode;
    reg                  expired;
    reg [31:0]           load;
    reg [31:0]           count;

    // Next-state values
    reg                  aw_held_d;
    reg [ADDR_WIDTH-1:0] aw_addr_d;
    reg                  w_held_d;
    reg [31:0]           w_data_d;
    reg [3:0]            w_strb_d;
    reg                  bvalid_d;
    reg [1:0]            bresp_d;
    reg                  rvalid_d;
    reg [31:0]           rdata_d;
    reg [1:0]            rresp_d;

    reg                  en_d;
    reg                  ie_d;
    reg                  mode_d;
    reg                  expired_d;
    reg [31:0]           load_d;
    reg [31:0]           count_d;

    reg [31:0]           rd_data_c;
    reg [1:0]            rd_resp_c;

    // ------------------------------------------------------------------
    // Channel handshakes
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire                  aw_fire  = s_axil_awvalid && s_axil_awready;
    wire                  w_fire   = s_axil_wvalid && s_axil_wready;
    wire                  ar_fire  = s_axil_arvalid && s_axil_arready;
    wire                  have_aw  = aw_held || aw_fire;
    wire                  have_w   = w_held || w_fire;
    wire                  do_write = have_aw && have_w;

    wire [ADDR_WIDTH-1:0] wr_addr  = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data  = w_held ? w_data_q : s_axil_wdata;
    wire [3:0]            wr_strb  = w_held ? w_strb_q : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: mapped only when word aligned and below 0x10
    // ------------------------------------------------------------------
    wire wr_hi_zero;
    wire rd_hi_zero;

    generate
        if (ADDR_WIDTH > 4) begin : g_hi
            assign wr_hi_zero = ~|wr_addr[ADDR_WIDTH-1:4];
            assign rd_hi_zero = ~|s_axil_araddr[ADDR_WIDTH-1:4];
        end else begin : g_nohi
            assign wr_hi_zero = 1'b1;
            assign rd_hi_zero = 1'b1;
        end
    endgenerate

    wire [1:0] wr_idx     = wr_addr[3:2];
    wire [1:0] rd_idx     = s_axil_araddr[3:2];
    wire       wr_mapped  = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
    wire       rd_mapped  = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;
    wire       wr_ok      = wr_mapped && (wr_idx != IDX_COUNT);
    wire       reg_we     = do_write && wr_ok;
    wire       ctrl_we    = reg_we && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire       load_we    = reg_we && (wr_idx == IDX_LOAD);
    wire       status_clr = reg_we && (wr_idx == IDX_STATUS) && wr_strb[0] && wr_data[0];

    // Last cycle of a count; a count of 0 is treated like 1
    wire       count_end  = en && (count <= 32'd1);

    assign irq = expired && ie;

    // ------------------------------------------------------------------
    // Write channel next state
    // ------------------------------------------------------------------
    always @* begin
        aw_held_d = aw_held;
        aw_addr_d = aw_addr_q;
        w_held_d  = w_held;
        w_data_d  = w_data_q;
        w_strb_d  = w_strb_q;
        bvalid_d  = s_axil_bvalid;
        bresp_d   = s_axil_bresp;

        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
            bvalid_d  = 1'b1;
            bresp_d   = wr_ok ? RESP_OKAY : RESP_SLVERR;
        end else begin
            if (aw_fire) begin
                aw_held_d = 1'b1;
                aw_addr_d = s_axil_awaddr;
            end
            if (w_fire) begin
                w_held_d = 1'b1;
                w_data_d = s_axil_wdata;
                w_strb_d = s_axil_wstrb;
            end
            if (s_axil_bready) begin
                bvalid_d = 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read data mux and read channel next state
    // ------------------------------------------------------------------
    always @* begin
        rd_data_c = 32'd0;
        rd_resp_c = RESP_SLVERR;
        if (rd_mapped) begin
            rd_resp_c = RESP_OKAY;
            case (rd_idx)
                IDX_CTRL:   rd_data_c = {29'd0, mode, ie, en};
                IDX_LOAD:   rd_data_c = load;
                IDX_COUNT:  rd_data_c = count;
                IDX_STATUS: rd_data_c = {31'd0, expired};
                default:    rd_data_c = 32'd0;
            endcase
        end
    end

    always @* begin
        rvalid_d = s_axil_rvalid;
        rdata_d  = s_axil_rdata;
        rresp_d  = s_axil_rresp;
        if (ar_fire) begin
            rvalid_d = 1'b1;
            rdata_d  = rd_data_c;
            rresp_d  = rd_resp_c;
        end else if (s_axil_rready) begin
            rvalid_d = 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Timer next state; later assignments win (spec priorities)
    // ------------------------------------------------------------------
    always @* begin
        en_d      = en;
        ie_d      = ie;
        mode_d    = mode;
        expired_d = expired;
        load_d    = load;
        count_d   = count;

        // 1. Count step: decrement, reload or stop
        if (en) begin
            if (count_end) begin
                if (mode) begin
                    count_d = load;
                end else begin
                    count_d = 32'd0;
                    en_d    = 1'b0;
                end
            end else begin
                count_d = count - 32'd1;
            end
        end

        // 2. EXPIRED: clear, then set; a count end beats a clear
        if (status_clr) begin
            expired_d = 1'b0;
        end
        if (count_end) begin
            expired_d = 1'b1;
        end

        // 3. CTRL write (wstrb[0] only); wins over the count step for EN and COUNT
        if (ctrl_we) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
            if (wr_data[0]) begin
                en_d    = 1'b1;
                count_d = load;
            end else begin
                en_d = 1'b0;
            end
        end

        // 4. LOAD write, byte merge
        if (load_we) begin
            if (wr_strb[0]) begin
                load_d[7:0] = wr_data[7:0];
            end
            if (wr_strb[1]) begin
                load_d[15:8] = wr_data[15:8];
            end
            if (wr_strb[2]) begin
                load_d[23:16] = wr_data[23:16];
            end
            if (wr_strb[3]) begin
                load_d[31:24] = wr_data[31:24];
            end
        end
    end

    // ------------------------------------------------------------------
    // Registers, synchronous active-low reset
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            aw_addr_q     <= {ADDR_WIDTH{1'b0}};
            w_held        <= 1'b0;
            w_data_q      <= 32'd0;
            w_strb_q      <= 4'd0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
            en            <= 1'b0;
            ie            <= 1'b0;
            mode          <= 1'b0;
            expired       <= 1'b0;
            load          <= 32'd0;
            count         <= 32'd0;
        end else begin
            aw_held       <= aw_held_d;
            aw_addr_q     <= aw_addr_d;
            w_held        <= w_held_d;
            w_data_q      <= w_data_d;
            w_strb_q      <= w_strb_d;
            s_axil_bvalid <= bvalid_d;
            s_axil_bresp  <= bresp_d;
            s_axil_rvalid <= rvalid_d;
            s_axil_rdata  <= rdata_d;
            s_axil_rresp  <= rresp_d;
            en            <= en_d;
            ie            <= ie_d;
            mode          <= mode_d;
            expired       <= expired_d;
            load          <= load_d;
            count         <= count_d;
        end
    end

endmodule

`default_nettype wire
=== END FILE ===
