`timescale 1ns / 1ps

// Self-checking testbench for axil_timer.
// axil_timer_tb is the top: it runs one lane at ADDR_WIDTH 4 and one at
// ADDR_WIDTH 8, sums their check counts and prints the verdict once.
//
// Timing convention: stimulus is driven just after a falling edge; cyc counts
// rising edges, so at a falling edge cyc is the number of the rising edge just
// passed. wr_edge is the edge on which a write took effect (the edge after
// which BVALID is first high); rise_edge[] holds the edges after which irq rose.

module axil_timer_tb_core #(
    parameter integer AW = 4
) (
    output reg         done,
    output wire [31:0] passed_o,
    output wire [31:0] failed_o
);
    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;

    reg          clk = 1'b0;
    reg          aresetn;
    reg [AW-1:0] awaddr;
    reg          awvalid;
    wire         awready;
    reg [31:0]   wdata;
    reg [3:0]    wstrb;
    reg          wvalid;
    wire         wready;
    wire [1:0]   bresp;
    wire         bvalid;
    reg          bready;
    reg [AW-1:0] araddr;
    reg          arvalid;
    wire         arready;
    wire [31:0]  rdata;
    wire [1:0]   rresp;
    wire         rvalid;
    reg          rready;
    wire         irq;

    integer passed;
    integer failed;
    integer cyc = 0;
    integer rise_cnt = 0;
    integer rise_edge [0:63];
    reg     irq_q = 1'b0;
    integer wr_edge;

    reg [31:0] m_load;
    reg [31:0] t_d;
    reg [31:0] old_load;
    reg [1:0]  t_r;
    integer    k;
    integer    base;
    integer    e;
    integer    s;
    integer    r_edge;
    integer    expc;

    assign passed_o = passed;
    assign failed_o = failed;

    axil_timer #(.ADDR_WIDTH(AW)) dut (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready),
        .irq            (irq)
    );

    always #5 clk = ~clk;

    always @(posedge clk) cyc <= cyc + 1;

    // irq rise monitor, sampled at falling edges
    always @(negedge clk) begin
        if (irq && !irq_q) begin
            rise_edge[rise_cnt[5:0]] <= cyc;
            rise_cnt <= rise_cnt + 1;
        end
        irq_q <= irq;
    end

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------
    function [AW-1:0] ad(input [7:0] a);
        begin
            ad = a[AW-1:0];
        end
    endfunction

    function [5:0] ix(input integer v);
        begin
            ix = v[5:0];
        end
    endfunction

    function [31:0] merge(input [31:0] o, input [31:0] d, input [3:0] st);
        begin
            merge = {st[3] ? d[31:24] : o[31:24],
                     st[2] ? d[23:16] : o[23:16],
                     st[1] ? d[15:8]  : o[15:8],
                     st[0] ? d[7:0]   : o[7:0]};
        end
    endfunction

    task automatic check_eq(input [31:0] got, input [31:0] expv, input integer id);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("axil_timer_tb AW=%0d check %0d failed: got 0x%08h, expected 0x%08h, edge %0d",
                       AW, id, got, expv, cyc);
            end
        end
    endtask

    task tick(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(posedge clk);
                @(negedge clk);
            end
        end
    endtask

    task wait_until(input integer t);
        begin
            while (cyc < t) begin
                @(posedge clk);
                @(negedge clk);
            end
        end
    endtask

    task wait_rises(input integer target, input integer limit);
        integer g;
        begin
            g = 0;
            while ((rise_cnt < target) && (g < limit)) begin
                tick(1);
                g = g + 1;
            end
        end
    endtask

    // order: 0 AW and W together, 1 AW first, 2 W first. bdelay: cycles of BREADY low.
    task axi_write(input [AW-1:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer bdelay, output [1:0] resp);
        integer i;
        integer guard;
        reg     aw_done;
        reg     w_done;
        reg     aw_go;
        reg     w_go;
        begin
            awaddr  = addr;
            wdata   = data;
            wstrb   = strb;
            bready  = 1'b0;
            aw_done = 1'b0;
            w_done  = 1'b0;
            awvalid = (order != 2);
            wvalid  = (order != 1);
            guard   = 0;
            while (!(aw_done && w_done) && (guard < 32)) begin
                aw_go = awvalid && awready;
                w_go  = wvalid && wready;
                @(posedge clk);
                @(negedge clk);
                guard = guard + 1;
                if (aw_go) begin
                    aw_done = 1'b1;
                    awvalid = 1'b0;
                end
                if (w_go) begin
                    w_done = 1'b1;
                    wvalid = 1'b0;
                end
                if (!(aw_done && w_done)) begin
                    check_eq({31'd0, bvalid}, 32'd0, 10);
                    if (aw_done) begin
                        check_eq({31'd0, awready}, 32'd0, 17);
                    end
                    if (w_done) begin
                        check_eq({31'd0, wready}, 32'd0, 18);
                    end
                    if ((order == 1) && aw_done) begin
                        wvalid = 1'b1;
                    end
                    if ((order == 2) && w_done) begin
                        awvalid = 1'b1;
                    end
                end
            end
            awvalid = 1'b0;
            wvalid  = 1'b0;
            check_eq({31'd0, aw_done && w_done}, 32'd1, 11);
            wr_edge = cyc;
            check_eq({31'd0, bvalid}, 32'd1, 12);
            resp = bresp;
            for (i = 0; i < bdelay; i = i + 1) begin
                @(posedge clk);
                @(negedge clk);
                check_eq({31'd0, bvalid}, 32'd1, 13);
                check_eq({30'd0, bresp}, {30'd0, resp}, 14);
                check_eq({30'd0, awready, wready}, 32'd0, 15);
            end
            bready = 1'b1;
            @(posedge clk);
            @(negedge clk);
            bready = 1'b0;
            check_eq({31'd0, bvalid}, 32'd0, 16);
        end
    endtask

    // rdelay: cycles of RREADY low
    task axi_read(input [AW-1:0] addr, input integer rdelay,
                  output [31:0] data, output [1:0] resp);
        integer i;
        integer guard;
        reg     ar_go;
        reg     ar_done;
        begin
            araddr  = addr;
            arvalid = 1'b1;
            rready  = 1'b0;
            ar_done = 1'b0;
            guard   = 0;
            while (!ar_done && (guard < 32)) begin
                ar_go = arvalid && arready;
                @(posedge clk);
                @(negedge clk);
                guard = guard + 1;
                if (ar_go) begin
                    ar_done = 1'b1;
                    arvalid = 1'b0;
                end
            end
            arvalid = 1'b0;
            check_eq({31'd0, ar_done}, 32'd1, 20);
            check_eq({31'd0, rvalid}, 32'd1, 21);
            data = rdata;
            resp = rresp;
            for (i = 0; i < rdelay; i = i + 1) begin
                @(posedge clk);
                @(negedge clk);
                check_eq({31'd0, rvalid}, 32'd1, 22);
                check_eq(rdata, data, 23);
                check_eq({30'd0, rresp}, {30'd0, resp}, 24);
                check_eq({31'd0, arready}, 32'd0, 25);
            end
            rready = 1'b1;
            @(posedge clk);
            @(negedge clk);
            rready = 1'b0;
            check_eq({31'd0, rvalid}, 32'd0, 26);
        end
    endtask

    task wr(input [7:0] a, input [31:0] d, input [3:0] st, input [1:0] expr, input integer id);
        reg [1:0] r;
        begin
            axi_write(ad(a), d, st, 0, 0, r);
            check_eq({30'd0, r}, {30'd0, expr}, id);
        end
    endtask

    task rd(input [7:0] a, input [31:0] expd, input [1:0] expr, input integer id);
        reg [31:0] d;
        reg [1:0]  r;
        begin
            axi_read(ad(a), 0, d, r);
            check_eq(d, expd, id);
            check_eq({30'd0, r}, {30'd0, expr}, id);
        end
    endtask

    task wr_load(input [31:0] data, input [3:0] st, input integer order,
                 input integer bdelay, input integer id);
        begin
            axi_write(ad(A_LOAD), data, st, order, bdelay, t_r);
            m_load = merge(m_load, data, st);
            check_eq({30'd0, t_r}, {30'd0, OKAY}, id);
            axi_read(ad(A_LOAD), bdelay, t_d, t_r);
            check_eq(t_d, m_load, id + 1);
            check_eq({30'd0, t_r}, {30'd0, OKAY}, id + 2);
        end
    endtask

    // One-shot count of LOAD n, timed to the edge; EN clears; no second interrupt
    task oneshot_case(input [31:0] n, input integer id);
        integer exp_n;
        integer b0;
        integer e0;
        begin
            exp_n = (n == 32'd0) ? 1 : n;
            wr(A_LOAD, n, 4'hF, OKAY, id);
            b0 = rise_cnt;
            wr(A_CTRL, 32'h3, 4'h1, OKAY, id + 1);
            e0 = wr_edge;
            wait_rises(b0 + 1, exp_n + 10);
            tick(2);
            check_eq(rise_cnt - b0, 1, id + 2);
            check_eq(rise_edge[ix(b0)] - e0, exp_n, id + 3);
            check_eq({31'd0, irq}, 32'd1, id + 4);
            rd(A_CTRL, 32'h2, OKAY, id + 5);
            rd(A_COUNT, 32'h0, OKAY, id + 6);
            rd(A_STATUS, 32'h1, OKAY, id + 7);
            wr(A_STATUS, 32'h1, 4'h1, OKAY, id + 8);
            check_eq({31'd0, irq}, 32'd0, id + 9);
            tick(2 * exp_n + 10);
            check_eq(rise_cnt - b0, 1, id + 10);
            rd(A_STATUS, 32'h0, OKAY, id + 11);
            rd(A_CTRL, 32'h2, OKAY, id + 12);
            rd(A_COUNT, 32'h0, OKAY, id + 13);
            wr(A_CTRL, 32'h0, 4'h1, OKAY, id + 14);
        end
    endtask

    // Periodic count of LOAD n (n >= 8), timed over several periods, then a stop
    task periodic_case(input [31:0] n, input integer periods, input integer id);
        integer b0;
        integer e0;
        integer s0;
        integer i;
        integer ph;
        integer cexp;
        begin
            wr(A_LOAD, n, 4'hF, OKAY, id);
            b0 = rise_cnt;
            wr(A_CTRL, 32'h7, 4'h1, OKAY, id + 1);
            e0 = wr_edge;
            for (i = 1; i <= periods; i = i + 1) begin
                wait_rises(b0 + i, n + 10);
                check_eq(rise_cnt - b0, i, id + 2);
                check_eq(rise_edge[ix(b0 + i - 1)] - e0, i * n, id + 3);
                wr(A_STATUS, 32'h1, 4'h1, OKAY, id + 4);
                check_eq({31'd0, irq}, 32'd0, id + 5);
            end
            rd(A_CTRL, 32'h7, OKAY, id + 6);
            wr(A_CTRL, 32'h6, 4'h1, OKAY, id + 7);
            s0 = wr_edge;
            check_eq((s0 - e0) / n, periods, id + 8);
            ph = (s0 - e0) % n;
            cexp = (ph == 0) ? n : n - ph;
            rd(A_COUNT, cexp, OKAY, id + 9);
            tick(3 * n);
            rd(A_COUNT, cexp, OKAY, id + 10);
            check_eq(rise_cnt - b0, periods, id + 11);
            rd(A_CTRL, 32'h6, OKAY, id + 12);
            rd(A_STATUS, 32'h0, OKAY, id + 13);
            wr(A_CTRL, 32'h0, 4'h1, OKAY, id + 14);
        end
    endtask

    // Periodic with a one-cycle period (LOAD 0 or 1): every edge ends a count,
    // so a clear never wins and a stop leaves COUNT at LOAD
    task periodic_one(input [31:0] n, input integer id);
        integer b0;
        integer e0;
        begin
            wr(A_LOAD, n, 4'hF, OKAY, id);
            b0 = rise_cnt;
            wr(A_CTRL, 32'h7, 4'h1, OKAY, id + 1);
            e0 = wr_edge;
            tick(4);
            check_eq(rise_cnt - b0, 1, id + 2);
            check_eq(rise_edge[ix(b0)] - e0, 1, id + 3);
            wr(A_STATUS, 32'h1, 4'h1, OKAY, id + 4);
            check_eq({31'd0, irq}, 32'd1, id + 5);
            rd(A_STATUS, 32'h1, OKAY, id + 6);
            rd(A_CTRL, 32'h7, OKAY, id + 7);
            wr(A_CTRL, 32'h6, 4'h1, OKAY, id + 8);
            rd(A_COUNT, n, OKAY, id + 9);
            rd(A_CTRL, 32'h6, OKAY, id + 10);
            wr(A_STATUS, 32'h1, 4'h1, OKAY, id + 11);
            check_eq({31'd0, irq}, 32'd0, id + 12);
            tick(5);
            check_eq(rise_cnt - b0, 1, id + 13);
            rd(A_STATUS, 32'h0, OKAY, id + 14);
            wr(A_CTRL, 32'h0, 4'h1, OKAY, id + 15);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        done    = 1'b0;
        passed  = 0;
        failed  = 0;
        aresetn = 1'b0;
        awaddr  = {AW{1'b0}};
        awvalid = 1'b0;
        wdata   = 32'd0;
        wstrb   = 4'd0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = {AW{1'b0}};
        arvalid = 1'b0;
        rready  = 1'b0;
        m_load  = 32'd0;

        @(negedge clk);
        tick(3);
        check_eq({31'd0, bvalid}, 32'd0, 1);
        check_eq({31'd0, rvalid}, 32'd0, 2);
        check_eq({31'd0, irq}, 32'd0, 3);
        aresetn = 1'b1;
        tick(1);
        check_eq({29'd0, awready, wready, arready}, 32'd7, 4);

        // ---- 100: reset values ----
        rd(A_CTRL,   32'd0, OKAY, 100);
        rd(A_LOAD,   32'd0, OKAY, 101);
        rd(A_COUNT,  32'd0, OKAY, 102);
        rd(A_STATUS, 32'd0, OKAY, 103);
        check_eq({31'd0, irq}, 32'd0, 104);

        // ---- 200: LOAD with partial strobes, channel orders, backpressure ----
        wr_load(32'h11223344, 4'hF,    0, 0, 200);
        wr_load(32'hAABBCCDD, 4'b0101, 1, 3, 203);
        wr_load(32'h55667788, 4'b1000, 2, 5, 206);
        wr_load(32'hFFFFFFFF, 4'b0000, 0, 2, 209);
        wr_load(32'h0000EE00, 4'b0010, 2, 0, 212);
        wr_load(32'h00000000, 4'b0110, 1, 1, 215);
        wr_load(32'h01020304, 4'b1001, 0, 0, 218);
        rd(A_LOAD, m_load, OKAY, 221);
        rd(A_LOAD, m_load, OKAY, 222);

        // ---- 300: COUNT read only; SLVERR policy; no aliasing ----
        wr(A_COUNT, 32'h5A5A5A5A, 4'hF, SLVERR, 300);
        rd(A_COUNT, 32'd0, OKAY, 301);
        rd(A_LOAD, m_load, OKAY, 302);
        for (k = 0; k < 16; k = k + 1) begin
            if (k[1:0] != 2'b00) begin
                wr(k[7:0], 32'hFFFFFFFF, 4'hF, SLVERR, 310);
                rd(k[7:0], 32'd0, SLVERR, 311);
            end
        end
        rd(A_CTRL,   32'd0,  OKAY, 312);
        rd(A_LOAD,   m_load, OKAY, 313);
        rd(A_COUNT,  32'd0,  OKAY, 314);
        rd(A_STATUS, 32'd0,  OKAY, 315);
        if (AW > 4) begin
            for (k = 16; k < 256; k = k + 4) begin
                wr(k[7:0], 32'hFFFFFFFF, 4'hF, SLVERR, 320);
                rd(k[7:0], 32'd0, SLVERR, 321);
            end
            wr(8'h11, 32'hFFFFFFFF, 4'hF, SLVERR, 322);
            rd(8'h11, 32'd0, SLVERR, 323);
            wr(8'hFF, 32'hFFFFFFFF, 4'hF, SLVERR, 324);
            rd(8'hFF, 32'd0, SLVERR, 325);
            rd(A_CTRL,   32'd0,  OKAY, 326);
            rd(A_LOAD,   m_load, OKAY, 327);
            rd(A_COUNT,  32'd0,  OKAY, 328);
            rd(A_STATUS, 32'd0,  OKAY, 329);
            check_eq({31'd0, irq}, 32'd0, 330);
        end

        // ---- 400: CTRL write without wstrb[0]; CTRL fields ----
        wr(A_CTRL, 32'h00000007, 4'hE, OKAY, 400);
        rd(A_CTRL, 32'd0, OKAY, 401);
        tick(5);
        rd(A_COUNT, 32'd0, OKAY, 402);
        rd(A_STATUS, 32'd0, OKAY, 403);
        check_eq({31'd0, irq}, 32'd0, 404);
        wr(A_CTRL, 32'hFFFFFFFE, 4'hF, OKAY, 405);
        rd(A_CTRL, 32'h6, OKAY, 406);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 407);
        rd(A_CTRL, 32'h0, OKAY, 408);

        // ---- 600: one-shot counts timed to the edge ----
        oneshot_case(32'd1,  600);
        oneshot_case(32'd2,  620);
        oneshot_case(32'd5,  640);
        oneshot_case(32'd17, 660);
        oneshot_case(32'd0,  680);
        oneshot_case(32'd40, 700 - 10);

        // ---- 710: interrupt enable on a pending expiry; STATUS write-1-clear ----
        wr(A_LOAD, 32'd4, 4'hF, OKAY, 710);
        base = rise_cnt;
        wr(A_CTRL, 32'h1, 4'h1, OKAY, 711);
        tick(10);
        check_eq({31'd0, irq}, 32'd0, 712);
        check_eq(rise_cnt - base, 0, 713);
        rd(A_STATUS, 32'h1, OKAY, 714);
        rd(A_CTRL, 32'h0, OKAY, 715);
        wr(A_CTRL, 32'h2, 4'h1, OKAY, 716);
        check_eq({31'd0, irq}, 32'd1, 717);
        check_eq(rise_cnt - base, 1, 718);
        check_eq(rise_edge[ix(base)], wr_edge, 719);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 720);
        check_eq({31'd0, irq}, 32'd0, 721);
        rd(A_STATUS, 32'h1, OKAY, 722);
        wr(A_CTRL, 32'h2, 4'h1, OKAY, 723);
        check_eq({31'd0, irq}, 32'd1, 724);
        wr(A_STATUS, 32'h0, 4'hF, OKAY, 725);
        check_eq({31'd0, irq}, 32'd1, 726);
        wr(A_STATUS, 32'h1, 4'hE, OKAY, 727);
        check_eq({31'd0, irq}, 32'd1, 728);
        rd(A_STATUS, 32'h1, OKAY, 729);
        wr(A_STATUS, 32'hFFFFFFFF, 4'h1, OKAY, 730);
        check_eq({31'd0, irq}, 32'd0, 731);
        rd(A_STATUS, 32'h0, OKAY, 732);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 733);

        // ---- 800: periodic counts timed over several periods, then stop ----
        periodic_case(32'd8,  4, 800);
        periodic_case(32'd13, 3, 820);
        periodic_one(32'd1, 840);
        periodic_one(32'd0, 860);

        // ---- 900: a count end beats a STATUS clear on the same edge ----
        wr(A_LOAD, 32'd10, 4'hF, OKAY, 900);
        base = rise_cnt;
        wr(A_CTRL, 32'h7, 4'h1, OKAY, 901);
        e = wr_edge;
        wait_rises(base + 1, 20);
        check_eq(rise_edge[ix(base)] - e, 10, 902);
        wait_until(e + 19);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 903);
        check_eq(wr_edge - e, 20, 904);
        check_eq({31'd0, irq}, 32'd1, 905);
        rd(A_STATUS, 32'h1, OKAY, 906);
        check_eq(rise_cnt - base, 1, 907);
        wait_until(e + 24);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 908);
        check_eq({31'd0, irq}, 32'd0, 909);
        wait_rises(base + 2, 20);
        check_eq(rise_edge[ix(base + 1)] - e, 30, 910);
        wr(A_CTRL, 32'h2, 4'h1, OKAY, 911);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 912);
        check_eq({31'd0, irq}, 32'd0, 913);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 914);

        // ---- 1000: CTRL write on the edge a count ends: the write wins ----
        // one-shot, EN 1 restarts from LOAD; EXPIRED still set
        wr(A_LOAD, 32'd8, 4'hF, OKAY, 1000);
        base = rise_cnt;
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1001);
        e = wr_edge;
        wait_until(e + 7);
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1002);
        check_eq(wr_edge - e, 8, 1003);
        tick(1);
        check_eq(rise_cnt - base, 1, 1004);
        check_eq(rise_edge[ix(base)] - e, 8, 1005);
        rd(A_CTRL, 32'h3, OKAY, 1006);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 1007);
        check_eq({31'd0, irq}, 32'd0, 1008);
        wait_rises(base + 2, 20);
        check_eq(rise_edge[ix(base + 1)] - e, 16, 1009);
        tick(2);
        rd(A_CTRL, 32'h2, OKAY, 1010);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 1011);
        // periodic, EN 0 stops with COUNT at the reload value of that edge
        base = rise_cnt;
        wr(A_CTRL, 32'h7, 4'h1, OKAY, 1012);
        e = wr_edge;
        wait_until(e + 7);
        wr(A_CTRL, 32'h6, 4'h1, OKAY, 1013);
        check_eq(wr_edge - e, 8, 1014);
        tick(1);
        check_eq(rise_cnt - base, 1, 1015);
        check_eq(rise_edge[ix(base)] - e, 8, 1016);
        rd(A_CTRL, 32'h6, OKAY, 1017);
        rd(A_COUNT, 32'd8, OKAY, 1018);
        rd(A_STATUS, 32'h1, OKAY, 1019);
        tick(20);
        rd(A_COUNT, 32'd8, OKAY, 1020);
        check_eq(rise_cnt - base, 1, 1021);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 1022);
        check_eq({31'd0, irq}, 32'd0, 1023);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 1024);

        // ---- 1100: stop freezes COUNT; restart; restart while counting ----
        wr(A_LOAD, 32'd100, 4'hF, OKAY, 1100);
        base = rise_cnt;
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1101);
        e = wr_edge;
        tick(15);
        wr(A_COUNT, 32'h12345678, 4'hF, SLVERR, 1102);
        wr(A_CTRL, 32'h2, 4'h1, OKAY, 1103);
        s = wr_edge;
        expc = 100 - (s - e);
        rd(A_COUNT, expc, OKAY, 1104);
        tick(120);
        rd(A_COUNT, expc, OKAY, 1105);
        check_eq(rise_cnt - base, 0, 1106);
        rd(A_CTRL, 32'h2, OKAY, 1107);
        rd(A_STATUS, 32'h0, OKAY, 1108);
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1109);
        r_edge = wr_edge;
        wait_rises(base + 1, 120);
        check_eq(rise_edge[ix(base)] - r_edge, 100, 1110);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 1111);
        wr(A_LOAD, 32'd20, 4'hF, OKAY, 1112);
        base = rise_cnt;
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1113);
        e = wr_edge;
        wait_until(e + 9);
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1114);
        r_edge = wr_edge;
        check_eq(r_edge - e, 10, 1115);
        wait_rises(base + 1, 40);
        check_eq(rise_edge[ix(base)] - r_edge, 20, 1116);
        tick(30);
        check_eq(rise_cnt - base, 1, 1117);
        rd(A_CTRL, 32'h2, OKAY, 1118);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 1119);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 1120);

        // ---- 1200: a read and a write on the same clock ----
        old_load = 32'hCAFEF00D;
        wr(A_LOAD, old_load, 4'hF, OKAY, 1200);
        awaddr  = ad(A_LOAD);
        wdata   = 32'h0BADBEEF;
        wstrb   = 4'hF;
        awvalid = 1'b1;
        wvalid  = 1'b1;
        araddr  = ad(A_LOAD);
        arvalid = 1'b1;
        check_eq({29'd0, awready, wready, arready}, 32'd7, 1201);
        tick(1);
        awvalid = 1'b0;
        wvalid  = 1'b0;
        arvalid = 1'b0;
        check_eq({31'd0, bvalid}, 32'd1, 1202);
        check_eq({30'd0, bresp}, {30'd0, OKAY}, 1203);
        check_eq({31'd0, rvalid}, 32'd1, 1204);
        check_eq(rdata, old_load, 1205);
        check_eq({30'd0, rresp}, {30'd0, OKAY}, 1206);
        bready = 1'b1;
        rready = 1'b1;
        tick(1);
        bready = 1'b0;
        rready = 1'b0;
        check_eq({30'd0, bvalid, rvalid}, 32'd0, 1207);
        rd(A_LOAD, 32'h0BADBEEF, OKAY, 1208);

        // ---- 1300: reset during a count and with a held write address ----
        wr(A_LOAD, 32'd30, 4'hF, OKAY, 1300);
        base = rise_cnt;
        wr(A_CTRL, 32'h7, 4'h1, OKAY, 1301);
        tick(10);
        awaddr  = ad(A_LOAD);
        wdata   = 32'd0;
        wstrb   = 4'h0;
        awvalid = 1'b1;
        tick(1);
        awvalid = 1'b0;
        check_eq({30'd0, awready, wready}, 32'd1, 1302);
        aresetn = 1'b0;
        tick(2);
        check_eq({29'd0, bvalid, rvalid, irq}, 32'd0, 1303);
        aresetn = 1'b1;
        tick(1);
        check_eq({29'd0, awready, wready, arready}, 32'd7, 1304);
        check_eq({30'd0, bvalid, rvalid}, 32'd0, 1305);
        rd(A_CTRL,   32'd0, OKAY, 1306);
        rd(A_LOAD,   32'd0, OKAY, 1307);
        rd(A_COUNT,  32'd0, OKAY, 1308);
        rd(A_STATUS, 32'd0, OKAY, 1309);
        tick(40);
        check_eq(rise_cnt - base, 0, 1310);
        wr(A_LOAD, 32'd3, 4'hF, OKAY, 1311);
        base = rise_cnt;
        wr(A_CTRL, 32'h3, 4'h1, OKAY, 1312);
        e = wr_edge;
        wait_rises(base + 1, 20);
        check_eq(rise_edge[ix(base)] - e, 3, 1313);
        wr(A_STATUS, 32'h1, 4'h1, OKAY, 1314);
        wr(A_CTRL, 32'h0, 4'h1, OKAY, 1315);
        check_eq({31'd0, irq}, 32'd0, 1316);

        tick(2);
        done = 1'b1;
    end
endmodule

module axil_timer_tb;
    wire            done4;
    wire            done8;
    wire [31:0]     passed4;
    wire [31:0]     failed4;
    wire [31:0]     passed8;
    wire [31:0]     failed8;
    reg  [8*64-1:0] nonce;
    integer         ok;
    integer         guard;
    integer         passed;
    integer         failed;

    axil_timer_tb_core #(.AW(4)) u_aw4 (
        .done     (done4),
        .passed_o (passed4),
        .failed_o (failed4)
    );

    axil_timer_tb_core #(.AW(8)) u_aw8 (
        .done     (done8),
        .passed_o (passed8),
        .failed_o (failed8)
    );

    initial begin
        nonce = {64{8'h00}};
        ok    = $value$plusargs("nirmaan_nonce=%s", nonce);
        guard = 0;
        while (!(done4 && done8) && (guard < 20000)) begin
            #1000;
            guard = guard + 1;
        end
        passed = passed4 + passed8;
        failed = failed4 + failed8;
        if (!(done4 && done8)) begin
            failed = failed + 1;
            $error("axil_timer_tb: timeout, lanes not finished (aw4 done %0d, aw8 done %0d)",
                   done4, done8);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
